pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 depositAmount, uint256 zeroData) public {
        vm.assume(depositAmount > 0);
        vm.assume(target != address(c));
        vm.assume(target != address(0));

        // make a deposit to c so it has a balance
        vm.deal(address(this), depositAmount);
        (bool depOk,) = address(c).call{value: depositAmount}("");
        require(depOk, "deposit failed");

        // call sendMoney with zero value, but non-empty data, to trigger internal withdraw(0) later
        vm.deal(address(c), 0);
        bytes memory data = abi.encodeWithSelector(C.withdraw.selector, uint256(zeroData));
        vm.prank(c.owner());
        try c.sendMoney(target, 0, data) {}
        catch {}

        // now attempt to withdraw all remaining balance from c
        vm.prank(c.owner());
        try c.withdrawAll() {}
        catch {
            // the withdrawal should not revert; if it does, the property is violated
            assertTrue(false, "withdrawAll reverted unexpectedly");
        }

        assertTrue(true);
    }
}

