pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value) public {
        // 1. Keep _value within admissible bounds: contract must have enough balance to withdraw, but fuzzer can send any
        vm.assume(_value <= type(uint256).max);
        // 2. Setup: fund contract with _value ether via fallback to ensure it has enough to withdraw
        address sender = address(0x1234);
        vm.deal(sender, _value);
        vm.prank(sender);
        (bool sent, ) = address(c).call{value: _value}("");
        require(sent, "funding failed");
        // Record owner balance before
        uint256 ownerBalanceBefore = c.owner().balance;
        // 3. Withdraw as owner
        vm.prank(c.owner());
        try c.withdraw(_value) {
            uint256 ownerBalanceAfter = c.owner().balance;
            // General rule: owner's ether balance increased by exactly _value
            assertTrue(ownerBalanceAfter == ownerBalanceBefore + _value);
        } catch {
            // If revert, no balance change; rule still holds (no transfer occurred). In correct contract, with enough balance and owner call, it should not revert.
            assertTrue(false);
        }
    }
}

