contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        // Keep amount within admissible range: 1 wei up to the contract's balance after funding
        uint256 fund = 100 ether;
        vm.deal(address(c), fund);
        amount = bound(amount, 1, fund);

        // The owner withdraws 'amount'
        vm.prank(c.owner());
        c.withdraw(amount);

        // General rule: after the owner calls withdraw(amount), the contract's ETH balance must be exactly fund - amount
