pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, address _owner) public {
        vm.assume(_owner != address(0));
        vm.assume(_owner != address(this));
        vm.assume(_owner != address(c));

        // Set owner to a fuzzed address so msg.sender check passes
        vm.prank(address(this));
        c = new C();
        vm.prank(address(c));
        // Actually we need to deploy fresh C each time with fuzzed owner?
        // To test withdraw, caller must be owner. We'll deploy fresh C with fuzzed _owner as deployer.
        vm.prank(_owner);
        vm.deal(_owner, 1 ether);
        c = new C();
        vm.deal(address(c), 1 ether);

        // Record pre-state: contract has code
        uint256 codeSizeBefore = address(c).code.length;
        assertTrue(codeSizeBefore > 0);

        // call withdraw as owner
        vm.prank(_owner);
        c.withdraw(_value);

        // After withdraw, contract code must remain intact (reference preserves code, buggy selfdestruct removes it)
        uint256 codeSizeAfter = address(c).code.length;
        assertTrue(codeSizeAfter > 0);
    }
}

